import Latex from 'react-latex'

const LatexRenderer = ({ content, className = "" }) => {
  return (
    <div className={`flex flex-row items-center flex-wrap gap-1 ${className}`}>
      {content.split(/(\$\$?.*?\$\$?)/g).filter(p => p.trim()).map((part, index) => {
        const isInline = part.startsWith('$') && part.endsWith('$') && !part.startsWith('$$')
        const isDisplay = part.startsWith('$$') && part.endsWith('$$')

        if (isInline || isDisplay) {
          const latexContent = isDisplay ? part.slice(2, -2) : part.slice(1, -1)
          return (
            <span dir='ltr'>
              <Latex key={index} className="inline-block align-middle">
              {`${isDisplay ? '$$' : '$'}${latexContent}${isDisplay ? '$$' : '$'}`}
            </Latex>
            </span>
          )
        }

        return (
          <span key={index} className={className}>
            {part}
          </span>
        )
      })}
    </div>
  )
}

export default LatexRenderer