import React, {useState,useRef,useEffect} from 'react';
import {ChevronDown, ChevronUp } from 'lucide-react';
import { pdf } from '@react-pdf/renderer';
import ExerciseView from '../../Component/ExerciseView';
import { useLanguage } from '../../Contexts/LanguageContext';
import ExamDocument from "../../Services/ToolsPDF//ExamDocument";
import ExamAnswerDocument from "../../Services/ToolsPDF/ExamAnswerDocument";

const ExamCard = ({exam}) => {
  
  const { t } = useLanguage();

  const divRef = useRef(null);

  const [fontSize, setFontSize] = useState(15.5);
  const [isOpen, setIsOpen] = useState(false);
  const toggleDropdown = () => setIsOpen(!isOpen);

  useEffect(() => {
    const updateFontSize = () => {
      if (divRef.current) {
        const divWidth = divRef.current.offsetWidth;
        const a4Width = 780;
        const newFontSize = 15.5 * (divWidth / a4Width);
        setFontSize(newFontSize);
      }
    };

    updateFontSize();
    window.addEventListener('resize', updateFontSize);
    return () => window.removeEventListener('resize', updateFontSize);
  }, [divRef]);
  
  const handleDownload = async () => {
    try {
      // Generate the Exam PDF as a Blob
      const examBlob = await pdf(
        <ExamDocument
          exam={exam.exercises}
          year={exam.year}
          level={exam.level}
          material={exam.matriel}
          duration={exam.duration}
          school={exam.school}
        />
      ).toBlob();

      // Generate the Answer PDF as a Blob
      const answerBlob = await pdf(
        <ExamAnswerDocument
          exam={exam.exercises}
          year={exam.year}
          level={exam.level}
          material={exam.matriel}
          duration={exam.duration}
          school={exam.school}
        />
      ).toBlob();

      // Function to trigger download for a Blob
      const downloadBlob = (blob, fileName) => {
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      };

      // Download both PDFs
      downloadBlob(examBlob, 'exam.pdf');
      downloadBlob(answerBlob, 'answer.pdf');
    } catch (error) {
      console.error('Error generating or downloading PDFs:', error);
    }
  };

  const createdAtDate = new Date(exam.created_at);
  const formattedCreatedAt = createdAtDate.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
  return (
    <>
      <div
      key={exam._id}
      ref={divRef}
      className="w-full max-w-[794px] mx-auto bg-white border border-gray-300 rounded-lg shadow-lg mb-8"
      style={{ fontSize: `${fontSize}px` }}
      >
      <div className="exam-section">
      <div className="flex flex-col sm:flex-row justify-between items-center p-4 sm:p-6">
        <h1 className="text-xl sm:text-2xl font-semibold mb-4 sm:mb-0">{formattedCreatedAt}</h1>
        <button onClick={handleDownload} className='btn-primary'>Download the exam</button>
      </div>
      {exam.exercises.map((exercise, i) => (
      <>
        <div className="rounded-md overflow-hidden">
              <button
                onClick={toggleDropdown}
                className="w-full bg-secondary px-4 sm:px-8 py-4 flex justify-between items-center focus:outline-none focus:ring-2 focus:ring-gray-400"
                aria-expanded={isOpen}
              >
                <span className="text-lg font-medium text-black">
                  <h4 className="ml-2 sm:text-2xl font-semibold mb-4 sm:mb-0" style={{ fontSize: `${fontSize + 2}px` }}>
                    {t("Exercise")}:{i + 1}
                  </h4>
                </span>
                {isOpen ? <ChevronUp className="h-5 w-5 text-gray-600" /> : <ChevronDown className="h-5 w-5 text-gray-600" />}
              </button>
              <div
                className={`px-4 sm:px-8 transition-all duration-300 ease-in-out ${
                  isOpen ? 'opacity-100 py-4' : 'max-h-0 opacity-0'
                } overflow-hidden`}
              >
                <div>
                  {exercise.exercise.map((item, itemIndex) => (
                    <React.Fragment key={itemIndex}>
                      <ExerciseView key={itemIndex} item={item} rtl={exercise.rtl} itemIndex={itemIndex} />
                    </React.Fragment>
                      ))}
                </div>
              </div>
        </div>
      </>
      ))}
      </div>
      </div>
      
    </>
  );
  
};

export default ExamCard;