import { useState, useEffect } from 'react';
import { useLanguage } from "../../Contexts/LanguageContext";

const Language = () => {
    const { language: contextLanguage, setLanguage } = useLanguage();
    const [selectedLanguage, setSelectedLanguage] = useState(contextLanguage);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Sync local state with context when context changes
    useEffect(() => {
        setSelectedLanguage(contextLanguage);
    }, [contextLanguage]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        
        try {
            // Simulate API call - replace with your actual API call
            const response = await mockApiSaveLanguage(selectedLanguage);
            
            if (response.success) {
                setLanguage(selectedLanguage); // Update context only after successful save
            }
        } catch (error) {
            console.error('Save failed:', error);
            setSelectedLanguage(contextLanguage);
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className='bg-gray-100 py-10'>
            <div className="bg-white p-8 mx-auto rounded-lg shadow-md w-full max-w-lg">
                <h1 className="text-2xl font-bold mb-6">Language Settings</h1>
                <form className="space-y-4" onSubmit={handleSubmit}>
                    <div className="flex flex-col space-y-1.5">
                        <label htmlFor="language" className="input-primary">Select Language</label>
                        <select 
                            id="language" 
                            name="language" 
                            className="input-primary"
                            value={selectedLanguage}
                            onChange={(e) => setSelectedLanguage(e.target.value)}
                            disabled={isSubmitting}
                        >
                            <option value="en">English</option>
                            <option value="ar">العربية</option>
                        </select>
                    </div>
                    <button 
                        type="submit" 
                        className="w-full btn-primary"
                        disabled={isSubmitting}
                    >
                        {isSubmitting ? 'Saving...' : 'Save Settings'}
                    </button>
                </form>
            </div>
        </div>
    );
}

// Mock API function - replace with your actual API call
const mockApiSaveLanguage = async (language) => {
    await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate network delay
    // Simulate random success/failure - remove this in real implementation
    const shouldFail = Math.random() > 0.5;
    
    return shouldFail 
        ? { success: false, error: 'Server error' }
        : { success: true };
};

export default Language;