import { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useLanguage } from '../../Contexts/LanguageContext';
import { getTokenPayload } from '../../Services/getTokenPayload';
import api from '../../Services/api';

export default function ResetPassword() {
  const { t } = useLanguage();
  
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { state } = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    if (!state?.email) {
      navigate('/forgotPassword');
    }
  }, [state, navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (password !== confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }
    try {
        const response=await api.post(`/api/auth/resetPassword`, 
           { 
            email: state.email,
            newPassword: password 
          });
        const { token } = response.data;
        localStorage.setItem('token', token);
        const tokenPayload = getTokenPayload();
        const userRole = tokenPayload?.role;
        if (userRole === 'admin') {
          navigate('/');
        } else {
          navigate('/user');
        }
      } catch (err) {
          setError(err.response?.data?.message || 'Something went wrong. Please try again.');
      } finally {
        setLoading(false);
      }
  };

  return (
    <>
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded shadow-lg w-full max-w-lg">
        <h2 className="text-4xl text-center font-bold mb-2">{t("Reset_Password")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <label htmlFor="password" className="block text-sm font-medium">
              {t("New_Password")}
            </label>
            <input
              id="password"
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="confirmPassword" className="block text-sm font-medium">
              {t("Confirm_Password")}
            </label>
            <input
              id="confirmPassword"
              name="confirmPassword"
              type="password"
              required
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          {error && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={loading}
            className={`${
              loading
                ? 'btn-primary bg-secondary cursor-not-allowed'
                : 'btn-primary'
            } w-3/4 mx-auto`}
          >
            {loading ? t("Resetting...") : t("Reset_Password")}
          </button>
        </form>
      </div>
    </div>
    </>
  );
}