import {Text, View, StyleSheet, Font } from '@react-pdf/renderer';
import amiri from '../../Assets/Fonts/Tajwal.ttf';

Font.register({
  family: 'Amiri',
  src: amiri,
  format: "truetype",
});


const styles = StyleSheet.create({
  section: {
    paddingHorizontal: 10,
    fontFamily: 'Amiri',
    fontSize: 12,
    marginVertical:5,
    marginHorizontal:5,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 4,
    marginTop:4,
  },
  centerText: {
    textAlign: 'center',
    fontWeight: 'bold',
    fontSize: 14,
    marginTop:4,
  },
  header: {
    fontSize: 12,
    marginBottom: 4,
    marginTop:10,
    textAlign: 'center',
    fontFamily: 'Amiri',
  },
  text: {
    fontSize: 12,
    textAlign: 'right',
    fontFamily: 'Amiri',
  },
  horizontalLine: {
    height: 1,
    backgroundColor: '#000',
    width: '100%',
    marginBottom:6,
  },
});


const HeaderPDF = ({ year, level, material, duration, school }) => {
  return (
     <>
        <View style={styles.header}>
          <Text>الجمهورية الجزائرية الديمقراطية الشعبية</Text>
          <Text>وزارة التربية الوطنية</Text>
        </View>
        <View style={styles.section}>
        <View style={styles.horizontalLine} />
          <View style={styles.row}>
            <Text>{year}</Text>
            <Text>{school}</Text>
          </View>
          <View style={styles.row}>
            <Text>{duration}</Text>
            <Text>{level}</Text>
          </View>
          <View style={styles.horizontalLine} />
          <Text style={styles.centerText}>{material}</Text>
        </View>
      </>
  );
};

export default HeaderPDF;