import { useState, useEffect } from "react";
import { DragDropContext, Droppable, Draggable } from "@hello-pangea/dnd";
import { GripVertical } from 'lucide-react';
import Trimesters from "../../Assets/Data/Trimesters";
import difficulty from "../../Assets/Data/difficulty";
import ExerciseCard from "../../Layouts/User/ExerciseCard";
import useFetchData from "../../Hooks/useFetchDataUser";
import ExamPdf from "./ExamPdf";
import api from '../../Services/api'
import { Filters } from "../../Component/Filters";
import { filterExercises } from "../../utils/filterExercises";
import { getFilterExercises } from "../../utils/GetFliterExercises";
import { useHeader } from "../../Contexts/HeaderContext";
import ErrorPage from "../../Component/ErrorPage";

export default function CurrentExam() {
  const { updateHeader } = useHeader();

  const [selectedFilters, setSelectedFilters] = useState({
    level: "All",
    trimester: "All",
    material: "All",
    unit: "All",
    difficulty: "All",
  });

  const [reorderedExercises, setReorderedExercises] = useState([]);
  const [current, setCurrent] = useState([]);
  
  const [loadingExercise, setLoadingExercise] = useState(true);
  const [errorExercise, setErrorExercise] = useState(null);

  const {
    levels,
    favexercises,
    addedExercises,
    setSelectedLevel,
    setSelectedMatriel,
    setAddedExercises,
    matriels,
    filteredUnits,
    setFavexercises,
    loading,
    error,
  } = useFetchData();

  useEffect(() => {
    updateHeader({
      title: 'Current Exam'
    });

    return () => updateHeader({ title: ''});
  }, [updateHeader]);

  useEffect(() => {
    // Define the fetch function
    const fetchData = async () => {
      try {
        setLoadingExercise(true);
        const response = await api.get(`/api/exercises/user/current-exam`);
        setCurrent(response.data.exercises);
      } catch (err) {
        setErrorExercise(err?.response?.data || {message:err.message,status:500});
      } finally {
        setLoadingExercise(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const onlyCrunt =getFilterExercises(current,addedExercises);
    if (onlyCrunt.length) {
      setReorderedExercises(filterExercises(onlyCrunt,selectedFilters));
    }
  }, [current, selectedFilters, addedExercises]);

  const handleFilterChange = (filterType, value) => {
    setSelectedFilters((prevFilters) => ({
      ...prevFilters,
      [filterType]: value,
    }));

    if (filterType === "level") setSelectedLevel(value);
    if (filterType === "material") setSelectedMatriel(value);
  };

  const handleOnDragEnd = (result) => {
    if (!result.destination) return;

    const items = Array.from(reorderedExercises);
    const [movedItem] = items.splice(result.source.index, 1);
    items.splice(result.destination.index, 0, movedItem);

    setReorderedExercises(items);
  };
  if (loading || loadingExercise) return <div>Loading...</div>;
  if (error || errorExercise) return <ErrorPage error={error || errorExercise} />;
  return (
    <div className="container mx-auto p-4 bg-gray-100 min-h-screen">
      <Filters
        levels={levels}
        trimesters={Trimesters}
        materials={matriels}
        units={filteredUnits}
        difficulties={difficulty}
        selectedFilters={selectedFilters}
        onFilterChange={handleFilterChange}
      />

      <DragDropContext onDragEnd={handleOnDragEnd}>
        <Droppable droppableId="exercises">
          {(provided) => (
            <div
              {...provided.droppableProps}
              ref={provided.innerRef}
              className="w-full space-y-2"
            >
              {reorderedExercises.map((exercise, index) => (
                <Draggable key={exercise._id} draggableId={exercise._id} index={index}>
                  {(provided, snapshot) => (
                    <div
                      ref={provided.innerRef}
                      {...provided.draggableProps}
                      className={`p-2 bg-white shadow rounded ${
                        snapshot.isDragging ? "shadow-lg bg-gray-300" : ""
                      }`}
                    >
                      <div className="flex items-center">
                        <div {...provided.dragHandleProps} className="mr-2 cursor-move">
                          <GripVertical className="text-gray-400" />
                        </div>
                        <ExerciseCard
                          exercise={exercise}
                          favexercises={favexercises}
                          addedExercises={addedExercises}
                          setFavexercises={setFavexercises}
                          setAddedExercises={setAddedExercises}
                        />
                      </div>
                    </div>
                  )}
                </Draggable>
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
      <ExamPdf 
      exercises={reorderedExercises}
      setAddedExercises={setAddedExercises}
      setCurrent={setReorderedExercises} />
    </div>
  );
}