import { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useLanguage } from '../../Contexts/LanguageContext';
import api from '../../Services/api';

export default function VerifyCode() {
  const { t } = useLanguage();

  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resendDisabled, setResendDisabled] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const { state } = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    if (!state?.email) {
      navigate('/forgotPassword');
    }
  }, [state, navigate]);

  useEffect(() => {
    if (resendDisabled && timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else if (timeLeft === 0) {
      setResendDisabled(false);
      setTimeLeft(60);
    }
  }, [resendDisabled, timeLeft]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('')
    try {
        await api.post(`/api/auth/verifyPassResetCode`, 
           { 
            email: state.email,
            resetCode: code 
          });
        // const { message } = response.data;
        navigate('/resetPassword', { state: { email: state.email } });
      } catch (err) {
          setError(
              err.response?.data?.message || 'Something went wrong. Please try again.'
            );
          console.log(err)
      } finally {
        setLoading(false);
      }
  };

  const handleResend = async () => {
    setResendDisabled(true);
    try {
        await api.post(`/api/auth/forgotPassword`, { email:state.email });
      } catch (err) {
          setError(
              err.response?.data?.message || 'Something went wrong. Please try again.'
            );
          console.log(err)
      } finally {
        setLoading(false);
      }
  };

  return (
    <>
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded shadow-lg w-full max-w-lg">
        <h2 className="text-3xl text-center font-bold mb-2">{t("Verify_Code")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
          <label htmlFor="code" className="block text-sm font-medium">
              {t("Verification_Code")}
            </label>
            <input
              id="code"
              name="code"
              type="text"
              required
              value={code}
              onChange={(e) => setCode(e.target.value)}
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          {error && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={loading}
            className={`${
              loading
                ? 'btn-primary bg-secondary cursor-not-allowed'
                : 'btn-primary'
            } w-3/4 mx-auto`}
          >
            {loading ? t("Verifying...") : t("Verify_Code")}
          </button>
          <button
            type="button"
            onClick={handleResend}
            disabled={resendDisabled}
            className={`${
              loading
                ? 'btn-primary bg-secondary cursor-not-allowed'
                : 'btn-primary'
            } w-3/4 mx-auto`}
          >
             {t('Resend_Code')}{resendDisabled && `(${timeLeft}s)`}
          </button>
        </form>
      </div>
    </div>
    </>
  );
}