import { useState, useEffect } from "react";
import { Download } from 'lucide-react';
import { pdf  } from '@react-pdf/renderer';
import Modal from "../../Component/Modal";
import ExamDocument from "../../Services/ToolsPDF//ExamDocument";
import ExamAnswerDocument from "../../Services/ToolsPDF/ExamAnswerDocument";
import api from "../../Services/api";
import { Snackbar }  from '@mui/material';
import StatusModal from '../../Component/StatusModal';
import { useHeader } from "../../Contexts/HeaderContext";
import { useLanguage } from "../../Contexts/LanguageContext";

const ExamPdf = ({ exercises,setAddedExercises ,setCurrent}) => {
  const { t } = useLanguage();
  const { updateHeader } = useHeader();
  
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [year, setYear] = useState("2025:السنة الدراسية");
  const [level, setLevel] = useState("المستوى:الاولى ابتدائي");
  const [matriel, setMatriel] = useState("اختبار في مادةاللغة العربية");
  const [duration, setDuration] = useState("1:30:المدة");
  const [school, setSchool] = useState("المتوسطة: اسم المؤسسة");

  const [error, setError] = useState(null);
  const [isErrorOpen, setIsErrorOpen] = useState(false);

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');

  useEffect(() => {
    updateHeader({
      buttons: (
        <button
        onClick={() => setIsModalOpen(true)}
        className="btn-primary inline-flex"
      >
        <span className="pr-2">
        <Download />
        </span>
         {t("Download_Exercises_PDF")}
      </button>
      )
    });

    return () => updateHeader({buttons: null });
  }, [t,updateHeader]);

  const handleDownload = async () => {
    try {
      // Generate the Exam PDF as a Blob
      const examBlob = await pdf(
        <ExamDocument
          exam={exercises}
          year={year}
          level={level}
          material={matriel}
          duration={duration}
          school={school}
        />
      ).toBlob();

      // Generate the Answer PDF as a Blob
      const answerBlob = await pdf(
        <ExamAnswerDocument
          exam={exercises}
          year={year}
          level={level}
          material={matriel}
          duration={duration}
          school={school}
        />
      ).toBlob();

      // Function to trigger download for a Blob
      const downloadBlob = (blob, fileName) => {
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      };

      // Download both PDFs
      downloadBlob(examBlob, 'exam.pdf');
      downloadBlob(answerBlob, 'answer.pdf');
    } catch (error) {
      console.error('Error generating or downloading PDFs:', error);
    }
    try {
      await api.post('/api/user/current/archive',{year,level,matriel,duration,school});
      setSnackbarMessage('This Exam add to archive successfully.');
      setSnackbarOpen(true);
      setIsModalOpen(false)
    } catch (error) {
      console.error("Error added to favorit service:", error);
      setError('Exercises has not delete from favorit');
      setIsErrorOpen(true);
    }
  };

  const handelSubmit =async(event)=>{
    event.preventDefault();
  }
  return (
    <div>
      {isModalOpen && (
        <Modal onClose={() => setIsModalOpen(false)}>
          <div className="popover-content min-w-80 sm:min-w-[300px] sm:max-w-[600px]">
            <div className="space-y-4">
              <div className="space-y-2">
                <h3 className="text-lg font-medium">Add exam details</h3>
              </div>
              <form className="grid gap-4" onSubmit={handelSubmit}>
                <div>
                  <div className="mb-4">
                    <label htmlFor="year" className="block text-sm font-bold text-gray-700 mb-2">
                      year:
                    </label>
                    <input
                      type="text"
                      name="year"
                      value={year}
                      onChange={(e) => setYear(e.target.value)}
                      className="block w-full mb-2 border border-muted p-2 rounded"
                    />
                  </div>
                  <div className="mb-4">
                    <label htmlFor="level" className="block text-sm font-bold text-gray-700 mb-2">
                      level:
                    </label>
                    <input
                      type="text"
                      name="level"
                      value={level}
                      onChange={(e) => setLevel(e.target.value)}
                      className="block w-full mb-2 border border-muted p-2 rounded"
                    />
                  </div>
                  <div className="mb-4">
                    <label htmlFor="matriel" className="block text-sm font-bold text-gray-700 mb-2">
                     matriel:
                    </label>
                    <input
                      type="text"
                      name="matriel"
                      value={matriel}
                      onChange={(e) => setMatriel(e.target.value)}
                      className="block w-full mb-2 border border-muted p-2 rounded"
                    />
                  </div>
                  <div className="mb-4">
                    <label htmlFor="duration" className="block text-sm font-bold text-gray-700 mb-2">
                    duration:
                    </label>
                    <input
                      type="text"
                      name="duration"
                      value={duration}
                      onChange={(e) => setDuration(e.target.value)}
                      className="block w-full mb-2 border border-muted p-2 rounded"
                    />
                  </div>
                  <div className="mb-4">
                    <label htmlFor="school" className="block text-sm font-bold text-gray-700 mb-2">
                    school:
                    </label>
                    <input
                      type="text"
                      name="school"
                      value={school}
                      onChange={(e) => setSchool(e.target.value)}
                      className="block w-full mb-2 border border-muted p-2 rounded"
                    />
                  </div>
                </div>
                <button
                  className="inline-flex items-center justify-center whitespace-nowrap btn-primary h-10"
                  onClick={handleDownload} > 
                 Exam PDF
                </button>
              </form>
            </div>
          </div>
        </Modal>
      )}
      {error && (
        <StatusModal
          type="error"
          title="Error Occurred"
          message={error}
          isOpen={isErrorOpen}
          onClose={() => setIsErrorOpen(false)}
        />
      )}
      <Snackbar
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={() => setSnackbarOpen(false)}
        message={snackbarMessage}/>
    </div>
  );
};

export default ExamPdf;