import LatexRenderer from "./LatexRenderer";

const ExerciseView = ({ item,itemIndex,rtl}) => {
  const textDirection = rtl ? "rtl" : "ltr";
  const imgDir = item.imagePosition === 'right' || item.imagePosition === 'left';
  const positionClassesMap = {
    right: 'flex-row',
    left: 'flex-row-reverse',
    top: 'flex-col-reverse',
    bottom: 'flex-col',
  };

  return (
    <div >
      <div className={`flex ${positionClassesMap[item.imagePosition] || ''} mb-5 mx-4 md:mx-8`}>
        <div className={`exercise-content ${imgDir && 'w-1/2'}`} dir={textDirection}>
            <LatexRenderer 
             content={item.content}
             className="content text-[length:var(--font-size)] whitespace-pre-wrap text-black mt-3 mb-4"
             />
          <ol className={`${rtl ?'mr-5':'ml-5'} space-y-3 text-black leading-relaxed`}>
            {item.questions.map((q, qIndex) => (
              <li key={qIndex} className="whitespace-pre-wrap mb-2">
                <LatexRenderer content={q.question}/>
              </li>
            ))}
          </ol>
        </div>
        <div className={`flex align-center ${imgDir && 'w-1/2'}`}>
          {item.image && (
            <div
              className={`${
                item.image && item.secondImage ? 
                'w-1/2 m-3 my-auto mt-6' : `mx-auto ${imgDir ? 'w-full':'w-2/3 mt-6'}`
              }`}
            >
              <img
                src={item.image}
                alt={`Exercise details ${itemIndex}`}
                className='w-full'
              />
            </div>
          )}
          {item.secondImage && (
            <div
            className={`${
              item.image && item.secondImage ? 
              'w-1/2 m-3 my-auto mt-6' : `mx-auto ${imgDir ? 'w-full':'w-2/3 mt-6'}`
            }`}
            >
              <img
                src={item.secondImage}
                alt={`Exercise details 2 ${itemIndex}`}
                className='w-full'
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ExerciseView;