import { Text, View, Image, StyleSheet } from '@react-pdf/renderer';

const styles = StyleSheet.create({
  list: {
    marginLeft: 20,
    fontSize: 12,
    fontFamily: 'Amiri',
    whiteSpace: 'pre-wrap',
  },
  listItem: {
    marginBottom: 5,
    whiteSpace: 'pre-wrap',
  },
  line: {
    fontFamily: 'Amiri',
    fontSize: 12,
    marginBottom: 5,
    lineHeight: 1.6,
  },
  flexCol: {
    flexDirection: 'column',
    marginBottom: 10,
  },
  imageContainer: {
    flexDirection: 'column',
    alignItems: 'center',
    margin:5,
  },
  image: {
    width: '100%',
  },
});

const AnswerViewLatino = ({ item }) => {
  return (
    <View style={styles.flexCol}>
      <View>
        <View style={styles.list}>
          {item.questions.map((q) => (
            <View key={q._id}>
              {q.answer.text
                .trim()
                .split(/\r?\n/)
                .map((line) => line.replace(/\t/g, ' ').trim())
                .filter((line) => line !== '')
                .map((line, i) => (
                  <Text key={`${q._id}-text-${i}`} style={styles.line}>
                    {line}
                  </Text>
                ))}

              {(q.answer.pictureAnswerOne || q.answer.pictureAnswerTwo) && (
                <View style={styles.imageContainer} key={`${q._id}-images`}>
                  {q.answer.pictureAnswerOne && (
                    <Image
                      key={`${q._id}-image-1`}
                      src={q.answer.pictureAnswerOne}
                      style={styles.image}
                    />
                  )}
                  {q.answer.pictureAnswerTwo && (
                    <Image
                      key={`${q._id}-image-2`}
                      src={q.answer.pictureAnswerTwo}
                      style={styles.image}
                    />
                  )}
                </View>
              )}
            </View>
          ))}
        </View>
      </View>
    </View>
  );
};

export default AnswerViewLatino;