import { useState } from 'react';
import { useNavigate,Link } from 'react-router-dom';
import api from '../../Services/api'
import { getTokenPayload } from '../../Services/getTokenPayload';
import { useLanguage } from '../../Contexts/LanguageContext';
const Login = () => {
  const { t } = useLanguage();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const response=await api.post(`/api/auth/login`, { email, password });
      const { token } = response.data;
      localStorage.setItem('token', token);
      const tokenPayload = getTokenPayload();
      const userRole = tokenPayload?.role;
      if (userRole === 'admin') {
        navigate('/');
      } else {
        navigate('/user');
      }
    } catch (err) {
        setError(
            err.response?.data?.message || 'Something went wrong. Please try again.'
          );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded shadow-lg w-full max-w-lg">
        <h2 className="text-4xl text-center font-bold mb-2">{t("loginMsg")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <label htmlFor="email" className="block text-sm font-medium">
              {t("email")}
            </label>
            <input
              id="email"
              type="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              requiredring
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium">
              {t("Password")}
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div className="text-primary text-right my-2 font-semibold">
          <Link to='/forgotPassword'> {t("FrogptPass")}</Link>
          </div>
          {error && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className={`${
              isLoading
                ? 'btn-primary bg-secondary cursor-not-allowed'
                : 'btn-primary'
            } w-3/4 mx-auto`}
          >
            {isLoading ? t("loadingMsg") : t("login")}
          </button>
          <div className="my-2 font-semibold text-center">
          dont have an account?
          <Link to='/signup' className='text-primary'> {t("signup")}</Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;