import { createContext, useContext, useState, useCallback } from 'react';

const HeaderContext = createContext();

export const HeaderProvider = ({ children }) => {
  const [headerState, setHeaderState] = useState({
    title: '',
    buttons: null
  });

  // Memoize updateHeader to prevent unnecessary identity changes
  const updateHeader = useCallback((newState) => {
    setHeaderState(prev => ({ ...prev, ...newState }));
  }, []); // Empty dependency array ensures the function is memoized once

  return (
    <HeaderContext.Provider value={{ ...headerState, updateHeader }}>
      {children}
    </HeaderContext.Provider>
  );
};

export const useHeader = () => {
  return useContext(HeaderContext);
};