import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import Multiselect from "multiselect-react-dropdown";
import api from '../../Services/api'
import useFetchData from '../../Hooks/useFetchDataSingup';
import { useLanguage } from '../../Contexts/LanguageContext';
const Signup = () => {
  const { t } = useLanguage();
  const [selectedLevels, setSelectedLevels] = useState([]);
  const [selectedMatriels, setSelectedMatriels] = useState([]);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const navigate = useNavigate();
 
  
  const { levels, matriels, loading, errorAPI } = useFetchData();
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const response=await api.post(`/api/auth/signup`, { name,email, password,phone,levels:selectedLevels,matirels:selectedMatriels });
      const { token } = response.data;
      localStorage.setItem('token', token);
      navigate('/user');
    } catch (err) {
        setError(
            err.response?.data?.message || 'Something went wrong. Please try again.'
          );
    } finally {
      setIsLoading(false);
    }
  };
 

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-2">{t("signup")}</h2>
        <p className="text-gray-500 text-sm mb-6">
          {t("signupMsg")}
        </p>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <label htmlFor="name" className="block text-sm font-medium">
              {t("name")}
            </label>
            <input
              id="name"
              type="text"
              placeholder=" You Name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm font-medium">
              {t("email")}
            </label>
            <input
              id="email"
              type="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="phone" className="block text-sm font-medium">
              {t("phone")}
            </label>
            <input
              id="phone"
              type="text"
              placeholder="876543210"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium">
              {t("Password")}
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium">
              {t("Levels")}
            </label>
            <Multiselect
              options={levels}
              selectedValues={selectedLevels}
              onSelect={(selectedList) => {
                selectedList.map((item) => item._id);
                setSelectedLevels(selectedList);
              }}
              onRemove={(selectedList) => {
                selectedList.map((item) => item._id);
                setSelectedLevels(selectedList);
              }}
              displayValue="name"
              placeholder="Select levels"
              style={{
                multiselectContainer: { backgroundColor: "white" },
                chips: { background: "#6366F1", color: "white" },
                optionContainer: { backgroundColor: "#F3F4F6" },
                option: { color: "#4B5563" },
              }}
              className='mx-3'
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium">
             {t("Matriels")}
            </label>
            <Multiselect
              options={matriels}
              selectedValues={selectedMatriels}
              onSelect={(selectedList) => {
                selectedList.map((item) => item._id);
                setSelectedMatriels(selectedList);
              }}
              onRemove={(selectedList) => {
                selectedList.map((item) => item._id);
                setSelectedMatriels(selectedList);
              }}
              displayValue="name"
              placeholder="Select matriels"
              style={{
                multiselectContainer: { backgroundColor: "white" },
                chips: { background: "#6366F1", color: "white" },
                optionContainer: { backgroundColor: "#F3F4F6" },
                option: { color: "#4B5563" },
              }}
              className='mx-3 rounded-md border-secodery'
            />
          </div>
          {(error || errorAPI) && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
              <span>{errorAPI}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={isLoading || loading}
            className={`w-3/4 mx-auto btn-primary`}
          >
            {isLoading || loading? t("loadingMsg") : t("signup")}
          </button>
          <div className="my-2 font-semibold">
          do you have account alredy?
          <Link to='/login' className='text-primary'>{t("login")}</Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Signup;