import { View, Image, StyleSheet } from '@react-pdf/renderer';
import LatexPDF from './LatexPDF';

const styles = StyleSheet.create({
  list: {
    marginLeft: 20,
    fontSize: 12,
    fontFamily: 'Amiri',
    whiteSpace: 'pre-wrap',
  },
  listItem: {
    marginBottom: 5,
    whiteSpace: 'pre-wrap',
  },
  flexCol: {
    flexDirection: 'column',
    marginBottom: 10,
  },
  image: {
    width: '100%',
  },
  contentText: {
    fontSize: 12,
    fontFamily: 'Amiri',
    whiteSpace: 'pre-wrap',
    direction: 'rtl',
    textAlign: 'right',
  },
  lineContainer: {
    flexDirection: 'row-reverse',
    marginBottom: 5,
  },
});

const AnswerViewArabic = ({ item }) => {
  return (
    <View style={styles.flexCol}>
      <View>
        <View style={styles.list}>
          {item?.questions.map((q) => (
            <View key={q._id}>
              {q.answer?.text
                ?.trim()
                ?.split(/\r?\n/)
                .map((line) => line.replace(/\t/g, ' ').trim())
                .filter((line) => line !== '')
                ?.map((line, i) => (
                  <View key={`${q._id}-text-${i}`} style={styles.lineContainer}>
                   <LatexPDF 
                     content={line} 
                     textStyle={styles.contentText} 
                   />
                  </View>
                ))}
              {(q.answer?.pictureAnswerOne || q.answer?.pictureAnswerTwo) && (
                <View style={styles.imageContainer} key={`${q._id}-images`}>
                  {q.answer.pictureAnswerOne && (
                    <Image
                      key={`${q._id}-image-1`}
                      src={q.answer.pictureAnswerOne}
                      style={styles.image}
                    />
                  )}
                  {q.answer.pictureAnswerTwo && (
                    <Image
                      key={`${q._id}-image-2`}
                      src={q.answer.pictureAnswerTwo}
                      style={styles.image}
                    />
                  )}
                </View>
              )}
            </View>
          ))}
        </View>
      </View>
    </View>
  );
};

export default AnswerViewArabic;