import { useState, useEffect } from 'react'
import api from '../../Services/api'
import ExamCard from '../../Layouts/User/ExamCard';
import { useHeader } from '../../Contexts/HeaderContext';
import ErrorPage from '../../Component/ErrorPage'

export default function ArchivedExams() {
  const { updateHeader } = useHeader();
  
  const [exercises, setExercises] = useState([]);
  
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    updateHeader({
      title: 'Archived_Exams'
    });

    return () => updateHeader({ title: ''});
  }, [updateHeader]);

    useEffect(() => {
      const fetchData = async () => {
        try {
          const response = await api.get(`/api/exercises/archivedExams`);
          
          setExercises(response.data.archivedExams);
        } catch (err) {
          setError(err?.response?.data || {message:err.message,status:500});
        } finally {
          setLoading(false);
        }
      };
  
      fetchData();
    }, []);
  if (loading) return <div>Loading...</div>;
  if (error) return <ErrorPage error={error} />;
  return (
    <div className="container mx-auto p-4 bg-gray-100 min-h-screen">
      <div className="w-full">
        {exercises.map(exercise => (
          <>
          <ExamCard key={exercise._id} 
           exam={exercise} />
          </>
        ))}
      </div>
    </div>
  )
}